from types import SimpleNamespace
from unittest.mock import patch

epoch = 1704182645.25

class FakeMoment:
    def __init__(self, formats):
        self.formats = formats

    def strftime(self, format_string):
        return self.formats[format_string]

local_now = FakeMoment({
    '%Y': '2024',
    '%m': '01',
    '%A': 'Tuesday',
    '%w': '2',
    '%W': '01',
    '%d': '02',
    '%H': '03',
    '%M': '04',
    '%S': '05',
    '%s': '1704182645',
    '%Y-%m-%d': '2024-01-02',
    '%H:%M:%S': '03:04:05',
    '%Y%m%dT%H%M%S%f': '20240102T030405250000',
    '%Y%m%dT%H%M%S': '20240102T030405',
})
utc_now = FakeMoment({
    '%Y-%m-%dT%H:%M:%S.%fZ': '2024-01-02T08:04:05.250000Z',
    '%Y-%m-%dT%H:%M:%SZ': '2024-01-02T08:04:05Z',
})

class FakeDateTime:
    @staticmethod
    def fromtimestamp(timestamp):
        assert timestamp == epoch
        return local_now

    @staticmethod
    def utcfromtimestamp(timestamp):
        assert timestamp == epoch
        return utc_now

class FakeTime:
    tzname = ('EST', 'EDT')

    @staticmethod
    def time():
        return epoch

